frappe.ui.form.on("Employee Warning", {
    warning_type: function(frm) {
        const templates = {
            "Verbal Warning":
`<p>It was observed that you <b>[describe misconduct/performance issue clearly, e.g., repeated lateness, failure to follow safety instructions]</b>. This matter was discussed with you verbally by your supervisor <b>[name]</b> in the presence of <b>[witness/HR representative]</b>.</p>
<p>You were informed that this behavior violates company policy and disrupts workplace discipline. The reason for this warning is to ensure you understand the seriousness of the issue and to give you the opportunity to correct it.</p>
<p>This verbal warning has been documented in your personnel file for record-keeping purposes.</p>`,

            "First Written Warning":
`<p>You engaged in <b>[specific misconduct, e.g., failure to complete assigned tasks, inappropriate behavior toward colleagues]</b>. This incident was investigated by the Disciplinary Committee on <b>[date]</b>, where evidence and witness statements were reviewed.</p>
<p>The Committee concluded that your actions violated company policy and affected workplace performance. You were given the opportunity to explain your side, but the reasons provided did not justify the misconduct.</p>
<p>This letter serves as a <b>formal written warning</b>. You are required to take immediate corrective action. Any recurrence of this behavior will result in a <b>final warning</b> or termination.</p>`,

            "Final Written Warning":
`<p>You were again involved in <b>[describe misconduct, e.g., repeated insubordination, violation of safety rules]</b> despite previous warnings issued on <b>[dates of prior warnings]</b>.</p>
<p>The matter was reviewed by the Disciplinary Committee on <b>[date]</b>, chaired by <b>[name]</b>, where the incident was thoroughly investigated. The Committee determined that your repeated misconduct demonstrates a failure to comply with company policy and instructions.</p>
<p>This letter serves as a <b>final written warning</b>. Any further misconduct or failure to improve will result in <b>termination of your employment</b> in accordance with Somaliland Labour Laws.</p>`,

            "Termination":
`<p>You committed <b>[describe misconduct, e.g., theft of company property, harassment of colleagues, repeated violation of attendance policy]</b>. This matter was investigated by the Disciplinary Committee on <b>[date]</b>, chaired by <b>[name]</b>, where evidence and witness testimonies were reviewed.</p>
<p>The Committee concluded that your actions constitute <b>gross misconduct</b> under company policy and Somaliland Labour Laws. You were given the opportunity to respond, but the reasons provided did not justify your actions.</p>
<p>Accordingly, your employment is terminated effective <b>[termination date]</b>. You will receive your final settlement, including any outstanding entitlements, in compliance with statutory requirements.</p>`
        };

        if (templates[frm.doc.warning_type]) {
            frm.set_value("description", templates[frm.doc.warning_type]);
        }
    }
});

frappe.ui.form.on('Performance KPI Items', {
    actual: function(frm, cdt, cdn) {
        calculate_score(frm, cdt, cdn);
    },
    target: function(frm, cdt, cdn) {
        calculate_score(frm, cdt, cdn);
    },
    weight_of_kpis: function(frm, cdt, cdn) {
        calculate_final(frm, cdt, cdn);
    },
    performance_kpi_items_remove: function(frm) {
        calculate_total(frm);
    }
});

frappe.ui.form.on('Performance KPIs', {
    refresh: function(frm) {
        calculate_total(frm);
    }
});

function calculate_score(frm, cdt, cdn) {
    let row = locals[cdt][cdn];
    if (row.target) {
        row.score = flt((row.actual / row.target) * 100, 2);
    } else {
        row.score = 0;
    }
    calculate_final(frm, cdt, cdn);
}

function calculate_final(frm, cdt, cdn) {
    let row = locals[cdt][cdn];
    row.final = flt((row.score * row.weight_of_kpis) / 100, 2);
    frm.refresh_field('performance_kpi_items');
    calculate_total(frm);
}

function calculate_total(frm) {
    let total = 0;
    (frm.doc.performance_kpi_items || []).forEach(row => {
        total += flt(row.final);
    });
    frm.set_value('total_final_score', total);
}
